import java.math.BigDecimal;
import java.time.LocalDate;

/** A plan form that passed validation; a null start takes the sheet's today. Exactly one of every and day is set. */
public record ValidPlan(BigDecimal amount, LocalDate start, Integer every, Integer day, LocalDate end, String user) {
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

/** Adds the plan to the person, audited as PLAN_ADDED. A blank start is the sheet's today; an end before the start is refused. */
public class SavePlan {
    public void save(@Val ValidPlan request, @Val Person person, Plans plans, Sheets sheets, Audit audit,
            ObjectResponse<ResponseEntity<PlanResponse>> response) throws InvalidPlanException {
        String sheetId = person.getSheetId();
        LocalDate start = request.start() != null ? request.start() : sheets.today(sheetId);
        if (request.end().isBefore(start)) {
            throw new InvalidPlanException("A plan's end cannot be before its start");
        }
        Plan plan = plans.add(sheetId, person.getId(), request.amount(), start, request.every(), request.day(), request.end());
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + request.user() + " name=" + person.getName()
                + " amount=" + plan.amount().toPlainString() + " start=" + plan.start() + (plan.day() != null ? " day=" + plan.day() : " every=" + plan.every()) + " end=" + plan.end());
        response.send(new ResponseEntity<>(PlanResponse.from(plan, sheets.today(sheetId)), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.plan.InvalidPlanException;
import net.officefloor.hq.app.plan.PlanRequest;
import net.officefloor.hq.app.plan.ValidPlan;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A plan's amount must be one the claim form takes for a new claim, its interval a whole number of days of at least 1
 *  or (instead) its day of the month a whole number from 1 to 31,
 *  its end a date (its start a date, or blank for the sheet's today). */
public class ValidatePlan {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PlanRequest request, Out<ValidPlan> body,
            Settings settings) throws InvalidPlanException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        java.math.BigDecimal amount;
        try {
            amount = ValidateClaim.amount(request.amount());
        } catch (InvalidClaimException e) {
            throw new InvalidPlanException(e.getMessage());
        }
        String every = request.every() == null ? "" : request.every().trim();
        String dayText = request.day() == null ? "" : request.day().trim();
        Integer days = null;
        Integer day = null;
        if (!dayText.isEmpty()) {
            if (!every.isEmpty()) {
                throw new InvalidPlanException("A plan runs either every N days or monthly on a day, not both");
            }
            if (!dayText.matches("\\d{1,2}") || (day = Integer.parseInt(dayText)) < 1 || day > 31) {
                throw new InvalidPlanException("A plan's day of the month must be a whole number from 1 to 31");
            }
        } else if (!every.matches("\\d{1,6}") || (days = Integer.parseInt(every)) < 1) {
            throw new InvalidPlanException("A plan's interval must be a whole number of days, at least 1");
        }
        LocalDate start = date(request.start(), true);
        LocalDate end = date(request.end(), false);
        if (start != null && end.isBefore(start)) {
            throw new InvalidPlanException("A plan's end cannot be before its start");
        }
        body.set(new ValidPlan(amount, start, days, day, end, request.user()));
    }

    private static LocalDate date(String raw, boolean blankAllowed) throws InvalidPlanException {
        String text = raw == null ? "" : raw.trim();
        if (text.isEmpty()) {
            if (blankAllowed) return null;
            throw new InvalidPlanException("A plan needs an end date");
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidPlanException("The date is not a date");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.plan.GenerateRequest;
import net.officefloor.hq.app.plan.GenerateResponse;
import net.officefloor.hq.app.plan.Plan;
import net.officefloor.hq.app.plan.Plans;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * For every plan on the sheet, in the order they were added, makes a DRAFT claim of the plan's amount for each plan date (the
 * start, then every N days; or the day in every month from the start's month, on the month's last day when it is shorter,
 * dates before the start left out) up to the end and the sheet's today that has none yet, dated that day with an empty note, each
 * audited as CLAIM_ADDED. A date the claim form refuses (its due-by inside a closed period, after the person's retirement) is
 * skipped, and tried again on the next generate. A viewer changes nothing: their generate makes no claim (an archived sheet
 * refuses it).
 */
public class GeneratePlanClaims {
    public void generate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateRequest request, Plans plans, People people,
            Claims claims, Sheets sheets, Periods periods, Holidays holidays, Settings settings, ClaimLog log, Audit audit,
            @Val RollupFigures before, Rollup rollup, ObjectResponse<GenerateResponse> response) {
        try {
            settings.refuseViewer(sheetId, request.user());
        } catch (ViewerRefusedException e) {
            response.send(new GenerateResponse(0));
            return;
        }
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        for (Plan plan : plans.list(sheetId)) {
            Person person = people.find(sheetId, plan.personId());
            if (person == null) continue;
            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
            for (LocalDate date : plan.dates(last)) {
                if (plans.made(plan.id(), date)) continue;
                LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsOnCreation(sheetId, person));
                if (periods.isClosed(sheetId, dueBy) || !person.allowsClaimOn(date)) continue;
                Claim claim = claims.add(sheetId, person.getId(), plan.amount(), date, "", null, dueBy, null);
                plans.recordMade(plan.id(), date, claim.getId());
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
                LateEntry.mark(claim, person, request.user(), claims, periods, audit);
                made++;
            }
        }
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new GenerateResponse(made));
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;

/** A plan as the screen shows it (amount with two decimals, dates as yyyy-mm-dd; every or day, the other null); nextDates are its
 *  first five plan dates after the sheet's today and on or before the end (none while paused); paused whether it is paused now;
 *  changes its amount changes, oldest first, each "<date> amount=<amount>". */
public record PlanResponse(String id, String personId, String amount, String start, Integer every, Integer day, String end, int generated,
        List<String> nextDates, boolean paused, List<String> changes) {
    public static PlanResponse from(Plan p, LocalDate today) {
        return new PlanResponse(String.valueOf(p.id()), String.valueOf(p.personId()), p.amount().toPlainString(), p.start().toString(),
                p.every(), p.day(), p.end().toString(), p.generated(), p.nextDates(today, 5).stream().map(LocalDate::toString).toList(), p.paused(),
                p.changes().stream().map(c -> c.on() + " amount=" + c.amount().toPlainString()).toList());
    }
}
-- A person's plans: an amount every N days from a start date to an end date, in the order they were
-- added (id). Generating makes a DRAFT claim for each plan date that has none yet.
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL,
    person_id  BIGINT         NOT NULL,
    amount     DECIMAL(19, 2) NOT NULL,
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL,
    end_date   DATE           NOT NULL
);
-- The plan dates a plan has made its claim for: each date at most once.
CREATE TABLE plan_claim (
    plan_id    BIGINT NOT NULL,
    claim_date DATE   NOT NULL,
    claim_id   BIGINT NOT NULL,
    PRIMARY KEY (plan_id, claim_date)
);
-- A plan's pauses: paused on a day and resumed on a later one (null while still paused). A plan date on or after
-- paused_on and before resumed_on is skipped, never made.
CREATE TABLE plan_pause (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id    BIGINT NOT NULL,
    paused_on  DATE   NOT NULL,
    resumed_on DATE
);
-- A plan's amount changes, in the order made: on the sheet's today the plan's amount became amount. plan.amount holds the
-- latest, which the claims generated from then on take; claims already generated keep theirs.
CREATE TABLE plan_change (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id    BIGINT        NOT NULL,
    changed_on DATE          NOT NULL,
    amount     DECIMAL(19, 2) NOT NULL
);
# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidatePlan
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: save
save:
